import type { WebApiAccessContext, WebApiRequests } from './api-client-accessors.js';
import { WebApiConnectionSettings, WebApiRequest } from './api-client-accessors.js';
import type { WebApiClientConfiguration } from './api-client.js';

/** Per-instance request selection; catalog projections never become component globals. */
export class WebApiSelection<
  TOutputs extends object,
  TInputs extends object,
  TDefaultHeaders extends object,
> {
  readonly #requests = new Map<string, WebApiRequest>();
  #selectedId: string | undefined;
  public readonly Connection: WebApiConnectionSettings<TDefaultHeaders>;
  public readonly Requests: WebApiRequests<TOutputs, TInputs>;

  public constructor(private readonly context: WebApiAccessContext) {
    this.#selectedId = context.readConfiguration().operations[0]?.id;
    this.Connection = new WebApiConnectionSettings<TDefaultHeaders>(context);
    this.Requests = new Proxy(Object.create(null) as object, {
      get: (_target, property) => {
        if (typeof property !== 'string') return undefined;
        const operation = context
          .readConfiguration()
          .operations.find((entry) => entry.name === property);
        return operation === undefined ? undefined : this.byId(operation.id);
      },
      has: (_target, property) =>
        typeof property === 'string' &&
        context.readConfiguration().operations.some((entry) => entry.name === property),
      ownKeys: () => context.readConfiguration().operations.map((entry) => entry.name),
      getOwnPropertyDescriptor: (_target, property) => {
        if (typeof property !== 'string') return undefined;
        const operation = context
          .readConfiguration()
          .operations.find((entry) => entry.name === property);
        return operation === undefined
          ? undefined
          : {
              configurable: true,
              enumerable: true,
              writable: false,
              value: this.byId(operation.id),
            };
      },
      set: () => {
        throw new TypeError('Modify request properties instead of replacing request instances.');
      },
      deleteProperty: () => {
        throw new TypeError('Modify the client configuration to remove a request.');
      },
      defineProperty: () => {
        throw new TypeError('Modify the client configuration to add requests.');
      },
      preventExtensions: () => false,
    }) as WebApiRequests<TOutputs, TInputs>;
  }

  public get selectedName(): string | undefined {
    return this.context
      .readConfiguration()
      .operations.find((operation) => operation.id === this.#selectedId)?.name;
  }

  public set selectedName(value: string | undefined) {
    if (value === undefined) {
      this.#selectedId = undefined;
      return;
    }
    const operation = this.context
      .readConfiguration()
      .operations.find((entry) => entry.name === value);
    if (operation === undefined) throw new RangeError(`API request "${value}" is not configured.`);
    this.#selectedId = operation.id;
  }

  public get active(): WebApiRequest {
    if (this.#selectedId === undefined)
      throw new RangeError('Select a configured API request before accessing its settings.');
    return this.byId(this.#selectedId);
  }

  public byName(name: string): WebApiRequest {
    const operation = this.context
      .readConfiguration()
      .operations.find((entry) => entry.name === name);
    if (operation === undefined) throw new RangeError(`API request "${name}" is not configured.`);
    return this.byId(operation.id);
  }

  private byId(id: string): WebApiRequest {
    this.context.readOperation(id);
    const existing = this.#requests.get(id);
    if (existing !== undefined) return existing;
    const request = new WebApiRequest(this.context, id);
    this.#requests.set(id, request);
    return request;
  }

  public changed(configuration: WebApiClientConfiguration): void {
    const ids = new Set(configuration.operations.map((operation) => operation.id));
    if (this.#selectedId !== undefined && !ids.has(this.#selectedId)) {
      this.#selectedId = configuration.operations[0]?.id;
    }
    for (const id of this.#requests.keys()) if (!ids.has(id)) this.#requests.delete(id);
  }
}

api-client-template.ts:
/** Browser-safe request-body templates shared by the IDE and generated applications. */
export const WEB_API_TEMPLATE_PARAMETER_TYPES = [
  'string',
  'number',
  'integer',
  'boolean',
  'object',
  'array',
  'null',
] as const;

export type WebApiTemplateParameterType = (typeof WEB_API_TEMPLATE_PARAMETER_TYPES)[number];

export interface WebApiTemplateParameter {
  readonly name: string;
  readonly type: WebApiTemplateParameterType;
}

export type WebApiTemplateValue =
  | string
  | number
  | boolean
  | null
  | readonly WebApiTemplateValue[]
  | { readonly [key: string]: WebApiTemplateValue };

export type WebApiTemplateValues = Readonly<Record<string, WebApiTemplateValue>>;

interface TemplateBody {
  readonly kind: 'none' | 'json' | 'text' | 'form-urlencoded' | 'form-data';
  readonly content: string;
  readonly parameters?: readonly WebApiTemplateParameter[];
}

function placeholderPattern(): RegExp {
  return /<\s*([\p{L}_$][\p{L}\p{N}_$.-]{0,119})\s*>/gu;
}

/** Derives unique names from the template and preserves existing type choices by name. */
export function getApiClientTemplateParameters(
  content: string,
  existing: readonly WebApiTemplateParameter[] = [],
): readonly WebApiTemplateParameter[] {
  const types = new Map(existing.map((parameter) => [parameter.name, parameter.type]));
  const names = new Set<string>();
  for (const match of content.matchAll(placeholderPattern())) {
    const name = match[1];
    if (name !== undefined) names.add(name);
    if (names.size > 200) throw new RangeError('A request body supports up to 200 parameters.');
  }
  return [...names].map((name) => ({ name, type: types.get(name) ?? 'string' }));
}

function parameterError(parameter: WebApiTemplateParameter, detail: string): TypeError {
  return new TypeError(`Parameter <${parameter.name}> ${detail}`);
}

function validateValue(
  parameter: WebApiTemplateParameter,
  value: unknown,
): asserts value is WebApiTemplateValue {
  const valid =
    parameter.type === 'null'
      ? value === null
      : parameter.type === 'string'
        ? typeof value === 'string'
        : parameter.type === 'boolean'
          ? typeof value === 'boolean'
          : parameter.type === 'number'
            ? typeof value === 'number' && Number.isFinite(value)
            : parameter.type === 'integer'
              ? typeof value === 'number' && Number.isSafeInteger(value)
              : parameter.type === 'array'
                ? Array.isArray(value)
                : parameter.type === 'object' &&
                  value !== null &&
                  typeof value === 'object' &&
                  !Array.isArray(value);
  if (!valid) throw parameterError(parameter, `requires a valid ${parameter.type} value.`);
}

/** Converts an IDE-only input into a typed value without evaluating source code. */
export function parseApiClientTemplateTestValue(
  parameter: WebApiTemplateParameter,
  input: string,
): WebApiTemplateValue {
  if (parameter.type === 'string') return input;
  if (parameter.type === 'null') return null;
  let value: unknown;
  try {
    value = JSON.parse(input);
  } catch {
    throw parameterError(parameter, `requires a valid ${parameter.type} value.`);
  }
  validateValue(parameter, value);
  return value;
}

function jsonValue(value: WebApiTemplateValue): string {
  const encoded = JSON.stringify(value, (_key, candidate: unknown) => {
    if (
      candidate === undefined ||
      typeof candidate === 'function' ||
      typeof candidate === 'symbol' ||
      typeof candidate === 'bigint' ||
      (typeof candidate === 'number' && !Number.isFinite(candidate))
    ) {
      throw new TypeError('Request parameters must contain valid JSON values.');
    }
    return candidate;
  });
  if (encoded === undefined) throw new TypeError('Request parameters must contain JSON values.');
  return encoded;
}

function textValue(value: WebApiTemplateValue): string {
  return typeof value === 'string' ? value : jsonValue(value);
}

/** Resolves a body template while preserving JSON types and escaping string contents. */
export function resolveApiClientBodyTemplate(
  body: TemplateBody,
  values: WebApiTemplateValues = {},
): string {
  if (body.kind === 'none') return body.content;
  const parameters = getApiClientTemplateParameters(body.content, body.parameters);
  if (parameters.length === 0) return body.content;
  const resolved = new Map<string, WebApiTemplateValue>();
  for (const parameter of parameters) {
    if (parameter.type !== 'null' && !Object.hasOwn(values, parameter.name)) {
      throw parameterError(parameter, 'requires a value.');
    }
    const value = parameter.type === 'null' ? null : values[parameter.name];
    validateValue(parameter, value);
    resolved.set(parameter.name, value);
  }
  const valueFor = (name: string): WebApiTemplateValue => {
    if (!resolved.has(name)) throw new TypeError(`Parameter <${name}> is not defined.`);
    return resolved.get(name) ?? null;
  };
  const resolveText = (content: string): string =>
    content.replace(placeholderPattern(), (_placeholder, name: string) =>
      textValue(valueFor(name)),
    );

  if (body.kind === 'text') return resolveText(body.content);
  if (body.kind === 'form-urlencoded' || body.kind === 'form-data') {
    const encoded = body.content.replace(placeholderPattern(), (_placeholder, name: string) =>
      encodeURIComponent(textValue(valueFor(name))),
    );
    return new URLSearchParams(encoded).toString();
  }

  let output = '';
  let position = 0;
  const matcher = new RegExp(placeholderPattern().source, 'uy');
  while (position < body.content.length) {
    const character = body.content[position];
    if (character !== '"') {
      if (character === '<') {
        matcher.lastIndex = position;
        const match = matcher.exec(body.content);
        if (match?.[1] !== undefined) {
          output += jsonValue(valueFor(match[1]));
          position += match[0].length;
          continue;
        }
      }
      output += character;
      position += 1;
      continue;
    }
    const start = position;
    position += 1;
    let closed = false;
    while (position < body.content.length) {
      const current = body.content[position];
      position += 1;
      if (current === '\\') position += 1;
      else if (current === '"') {
        closed = true;
        break;
      }
    }
    if (!closed)
      throw new TypeError('The configured JSON request body has an unterminated string.');
    const raw = body.content.slice(start, position);
    const text: unknown = JSON.parse(raw);
    if (typeof text !== 'string') throw new TypeError('Invalid JSON string in request body.');
    const placeholders = [...raw.slice(1, -1).matchAll(placeholderPattern())];
    const only = placeholders[0];
    const key = body.content.slice(position).trimStart().startsWith(':');
    output +=
      !key &&
      placeholders.length === 1 &&
      only !== undefined &&
      only[0] === raw.slice(1, -1) &&
      only[1] !== undefined
        ? jsonValue(valueFor(only[1]))
        : raw.replace(placeholderPattern(), (_placeholder, name: string) =>
            jsonValue(textValue(valueFor(name))).slice(1, -1),
          );
  }
  // Catch invalid template placement before any request reaches the network.
  JSON.parse(output);
  return output;
}

component.ts:
import type { RuntimeLayoutAlignSelf } from './layout.js';

export type WebComponentEventHandler<TSender = WebComponent> = (
  sender: TSender,
  event: Event,
) => void | Promise<void>;

export interface WebCurrentRowBinding {
  readonly property: string;
  readonly fieldPath: string;
}

const currentRowBindings = new WeakMap<HTMLElement, readonly WebCurrentRowBinding[]>();

const EVENT_NAME_MAP: Readonly<Record<string, string>> = Object.freeze({
  OnBlur: 'blur',
  OnChange: 'change',
  OnClick: 'click',
  OnCreate: 'webrad:create',
  OnDblClick: 'dblclick',
  OnFocus: 'focus',
  OnHide: 'webrad:hide',
  OnInput: 'input',
  OnLogin: 'webrad:login',
  OnLogout: 'webrad:logout',
  OnUnauthenticated: 'webrad:unauthenticated',
  OnKeyDown: 'keydown',
  OnKeyUp: 'keyup',
  OnMouseDown: 'mousedown',
  OnMouseEnter: 'mouseenter',
  OnMouseLeave: 'mouseleave',
  OnMouseUp: 'mouseup',
  OnResize: 'webrad:resize',
  OnRequest: 'webrad:request',
  OnSuccess: 'webrad:success',
  OnError: 'webrad:error',
  OnComplete: 'webrad:complete',
  OnShow: 'webrad:show',
});

export function runtimeEventName(eventName: string): string {
  const mapped = EVENT_NAME_MAP[eventName];
  if (mapped !== undefined) return mapped;
  return eventName.startsWith('On') ? eventName.slice(2).toLowerCase() : eventName;
}

function supportsDisabled(element: HTMLElement): element is HTMLElement & { disabled: boolean } {
  return 'disabled' in element && typeof element.disabled === 'boolean';
}

function finitePixels(value: number, property: string): string {
  if (!Number.isFinite(value)) {
    throw new RangeError(`${property} must be a finite number.`);
  }
  return `${String(value)}px`;
}

function pixelValue(value: string, fallback: number): number {
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export interface WebNonvisualComponentOptions {
  readonly id?: string;
  readonly name?: string;
}

/** Browser-safe identity shared by services that do not own a DOM element. */
export class WebNonvisualComponent {
  readonly #events = new EventTarget();
  readonly #eventDisposers = new Map<string, () => void>();
  public readonly id: string;
  public readonly name: string;

  public constructor(options: WebNonvisualComponentOptions = {}) {
    this.id = options.id ?? '';
    this.name = options.name ?? '';
  }

  /** Binds a generated page handler to a nonvisual component lifecycle event. */
  public bindEvent(eventName: string, handler: WebComponentEventHandler<this> | null): () => void {
    this.#eventDisposers.get(eventName)?.();
    this.#eventDisposers.delete(eventName);
    if (handler === null) return () => undefined;

    const listener: EventListener = (event) => {
      void handler(this, event);
    };
    const browserEventName = runtimeEventName(eventName);
    this.#events.addEventListener(browserEventName, listener);
    const dispose = (): void => {
      this.#events.removeEventListener(browserEventName, listener);
      if (this.#eventDisposers.get(eventName) === dispose) this.#eventDisposers.delete(eventName);
    };
    this.#eventDisposers.set(eventName, dispose);
    return dispose;
  }

  /** Emits a lifecycle event without requiring a DOM element. */
  public emit(eventName: string, detail?: unknown): boolean {
    return this.#events.dispatchEvent(
      new CustomEvent(runtimeEventName(eventName), { cancelable: true, detail }),
    );
  }

  public dispose(): void {
    for (const dispose of [...this.#eventDisposers.values()]) dispose();
    this.#eventDisposers.clear();
  }
}

/** Browser-side wrapper shared by every visual WebRAD component. */
export class WebComponent<TElement extends HTMLElement = HTMLElement> {
  readonly #eventDisposers = new Map<string, () => void>();

  public constructor(public readonly element: TElement) {}

  /** Declarative visual bindings shared by every wrapper for this element. */
  public get currentRowBindings(): readonly WebCurrentRowBinding[] {
    return currentRowBindings.get(this.element) ?? [];
  }

  public set currentRowBindings(bindings: readonly WebCurrentRowBinding[]) {
    const normalized = Object.freeze(bindings.map((binding) => Object.freeze({ ...binding })));
    currentRowBindings.set(this.element, normalized);
    this.element.dispatchEvent(
      new CustomEvent('webrad:row-bindings-change', { detail: normalized }),
    );
  }

  public get id(): string {
    return this.element.dataset.webradId ?? this.element.id;
  }

  public get name(): string {
    return this.element.dataset.webradName ?? '';
  }

  public get visible(): boolean {
    const stored = this.element.dataset.webradVisible;
    return stored === undefined ? !this.element.hidden : stored !== 'false';
  }

  public set visible(value: boolean) {
    this.element.dataset.webradVisible = String(value);
    this.#applyVisibility();
  }

  /** Whether an invisible component is removed from its parent layout. */
  public get collapseWhenHidden(): boolean {
    return this.element.dataset.webradCollapseWhenHidden !== 'false';
  }

  public set collapseWhenHidden(value: boolean) {
    this.element.dataset.webradCollapseWhenHidden = String(value);
    this.#applyVisibility();
  }

  #applyVisibility(): void {
    const visible = this.visible;
    const collapse = this.collapseWhenHidden;
    this.element.hidden = !visible && collapse;
    this.element.setAttribute('aria-hidden', String(!visible));

    if (!visible && !collapse) {
      this.element.style.setProperty('visibility', 'hidden', 'important');
    } else {
      this.element.style.removeProperty('visibility');
    }

    if (!visible && collapse) {
      // Layout uses inline !important for structural display so a reusable
      // style cannot turn a row or column into a different display mode. Keep
      // the visibility API authoritative over that structural projection.
      this.element.style.setProperty('display', 'none', 'important');
      return;
    }

    const layoutDisplay = this.element.dataset.webradLayoutDisplay;
    if (layoutDisplay === undefined) this.element.style.removeProperty('display');
    else this.element.style.setProperty('display', layoutDisplay, 'important');
  }

  public get enabled(): boolean {
    if (supportsDisabled(this.element)) return !this.element.disabled;
    return this.element.getAttribute('aria-disabled') !== 'true';
  }

  public set enabled(value: boolean) {
    if (supportsDisabled(this.element)) this.element.disabled = !value;
    this.element.setAttribute('aria-disabled', String(!value));
  }

  public get x(): number {
    return pixelValue(this.element.style.left, this.element.offsetLeft);
  }

  public set x(value: number) {
    this.element.style.left = finitePixels(value, 'x');
  }

  public get y(): number {
    return pixelValue(this.element.style.top, this.element.offsetTop);
  }

  public set y(value: number) {
    this.element.style.top = finitePixels(value, 'y');
  }

  public get width(): number {
    return pixelValue(this.element.style.width, this.element.offsetWidth);
  }

  public set width(value: number) {
    this.element.style.width = finitePixels(value, 'width');
  }

  public get height(): number {
    return pixelValue(this.element.style.height, this.element.offsetHeight);
  }

  public set height(value: number) {
    this.element.style.height = finitePixels(value, 'height');
  }

  public get tabIndex(): number {
    return this.element.tabIndex;
  }

  /** Cross-axis alignment in a row/column parent; auto inherits the parent. */
  public get alignSelf(): RuntimeLayoutAlignSelf {
    const value = this.element.style.alignSelf;
    if (value === 'flex-start') return 'start';
    if (value === 'flex-end') return 'end';
    return value === 'center' || value === 'stretch' ? value : 'auto';
  }

  public set alignSelf(value: RuntimeLayoutAlignSelf) {
    if (!['auto', 'start', 'center', 'end', 'stretch'].includes(value)) {
      throw new TypeError('alignSelf must be auto, start, center, end, or stretch.');
    }
    const css = value === 'start' ? 'flex-start' : value === 'end' ? 'flex-end' : value;
    this.element.style.setProperty('align-self', css, 'important');
  }

  /** Outer spacing on all four sides, in pixels. */
  public get margin(): number {
    return pixelValue(this.element.style.margin, 0);
  }

  public set margin(value: number) {
    this.element.style.margin = finitePixels(value, 'margin');
  }

  /** Outer spacing on the top side, in pixels. */
  public get marginTop(): number {
    return pixelValue(this.element.style.marginTop || getComputedStyle(this.element).marginTop, 0);
  }

  public set marginTop(value: number) {
    this.element.style.marginTop = finitePixels(value, 'marginTop');
  }

  /** Outer spacing on the right side, in pixels. */
  public get marginRight(): number {
    return pixelValue(
      this.element.style.marginRight || getComputedStyle(this.element).marginRight,
      0,
    );
  }

  public set marginRight(value: number) {
    this.element.style.marginRight = finitePixels(value, 'marginRight');
  }

  /** Outer spacing on the bottom side, in pixels. */
  public get marginBottom(): number {
    return pixelValue(
      this.element.style.marginBottom || getComputedStyle(this.element).marginBottom,
      0,
    );
  }

  public set marginBottom(value: number) {
    this.element.style.marginBottom = finitePixels(value, 'marginBottom');
  }

  /** Outer spacing on the left side, in pixels. */
  public get marginLeft(): number {
    return pixelValue(
      this.element.style.marginLeft || getComputedStyle(this.element).marginLeft,
      0,
    );
  }

  public set marginLeft(value: number) {
    this.element.style.marginLeft = finitePixels(value, 'marginLeft');
  }

  public set tabIndex(value: number) {
    this.element.tabIndex = value;
  }

  public get backgroundColor(): string {
    return this.element.style.backgroundColor;
  }

  public set backgroundColor(value: string) {
    this.element.style.backgroundColor = value;
  }

  public get color(): string {
    return this.element.style.color;
  }

  public set color(value: string) {
    this.element.style.color = value;
  }

  public get borderColor(): string {
    return this.element.style.borderColor;
  }

  public set borderColor(value: string) {
    this.element.style.borderColor = value;
  }

  public focus(options?: FocusOptions): void {
    this.element.focus(options);
  }

  public show(): void {
    this.visible = true;
  }

  public hide(): void {
    this.visible = false;
  }

  public bindEvent(eventName: string, handler: WebComponentEventHandler<this> | null): () => void {
    this.#eventDisposers.get(eventName)?.();
    this.#eventDisposers.delete(eventName);
    if (handler === null) return () => undefined;

    const browserEventName = runtimeEventName(eventName);
    const listener: EventListener = (event) => {
      void handler(this, event);
    };
    this.element.addEventListener(browserEventName, listener);
    const dispose = (): void => {
      this.element.removeEventListener(browserEventName, listener);
      if (this.#eventDisposers.get(eventName) === dispose) this.#eventDisposers.delete(eventName);
    };
    this.#eventDisposers.set(eventName, dispose);
    return dispose;
  }

  public emit(eventName: string, detail?: unknown): boolean {
    return this.element.dispatchEvent(
      new CustomEvent(runtimeEventName(eventName), { bubbles: false, cancelable: true, detail }),
    );
  }

  public dispose(): void {
    for (const dispose of [...this.#eventDisposers.values()]) dispose();
    this.#eventDisposers.clear();
  }
}

